  // ---- month names, for dates we format ourselves ------------------
  // The browser's own formatter is not dependable here: some builds ship a
  // reduced ICU table and render Uzbek as "2026 M06 22". Uzbek is the primary
  // locale, so the names live in the catalogue like every other string. The
  // Russian forms are genitive because they always follow a day number.
  // The three weekday rows the grid labels, for the same reason as the months.
  "wd.mon":       { uz: "Du", ru: "Пн", en: "Mon" },
  "wd.wed":       { uz: "Ço", ru: "Ср", en: "Wed" },
  "wd.fri":       { uz: "Ju", ru: "Пт", en: "Fri" },
  // The activity strip only ever labels three rows, so the other four were
  // never needed. The learning calendar draws a full week, and deriving those
  // four from Intl while these three come from the catalogue would put two
  // different spellings of the same week on one screen.
  "wd.tue":       { uz: "Se", ru: "Вт", en: "Tue" },
  "wd.thu":       { uz: "Pay", ru: "Чт", en: "Thu" },
  "wd.sat":       { uz: "Şa", ru: "Сб", en: "Sat" },
  "wd.sun":       { uz: "Yak", ru: "Вс", en: "Sun" },
