  "ad.signInHint":        { uz: "Boşqaruv paneli xodimlar uçun. Login va parol bilan kiring.", ru: "Панель управления — для сотрудников. Войдите с логином и паролем.", en: "The management panel is for staff. Sign in with your login and password." },
  "an.tab":               { uz: "Tahlil", ru: "Аналитика", en: "Analytics" },
