  "an.h.visited":         { uz: "Akkaunt bilan kirganlar", ru: "Заходили с аккаунтом", en: "Visited signed in" },
  "an.active.note":       { uz: "Faollik — qilingan iş: kurs, diagnostika, reja, rezyume, yordamçi, ariza. Faqat sahifa oçiş faollik hisoblanmaydi va alohida körsatiladi.", ru: "Активность — это действие: курс, диагностика, план, резюме, ассистент, заявка. Просто открытая страница активностью не считается и показана отдельно.", en: "Active means a recorded action: a course, a diagnostic, a plan, a CV entry, an assistant question, an application. A page view alone does not count and is shown separately." },
  "an.q.visitors":        { uz: "Qança odam keldi?", ru: "Сколько людей пришло?", en: "How many people came?" },
